sed -i 's/validate_bash_command_rejects_external_path_arguments() {/validate_bash_command_rejects_external_path_arguments() {\n        let tempdir = tempfile::tempdir().expect("tempdir");\n        let safety = ShellSafety::new(ShellAllowlist {\n            executables: vec!["ls".to_string()],\n            cwd_roots: vec![".".to_string()],\n            ..ShellAllowlist::default()\n        });\n        let err = safety.validate_bash_command("ls -I../../../etc/passwd", tempdir.path(), tempdir.path()).expect_err("external relative path in short option should be blocked");\n        assert!(matches!(err, ToolError::PathEscapesWorkspace { .. }));/' crates/harness-tools/src/shell_safety.rs
